import heapq


def dependency_solver(name_order, preference):
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        initial = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
        best_key = None
        best = None
        names = sorted(packages, reverse=(name_order == "descending"))

        def cyclic(edges):
            done, active = set(), set()
            def visit(node):
                if node in active:
                    return True
                if node in done:
                    return False
                active.add(node)
                if any(visit(other) for other in edges.get(node, ())):
                    return True
                active.remove(node)
                done.add(node)
                return False
            return any(visit(node) for node in edges)

        def search(req, chosen, edges):
            nonlocal best_key, best
            todo = [n for n in req if n not in chosen]
            if not todo:
                key = tuple(chosen.get(n, -1) for n in names)
                if best_key is None or (key > best_key if preference == "maximum" else key < best_key):
                    best_key, best = key, chosen
                return
            name = todo[0]
            bounds = req[name]
            blocked = set(data.get("blocked", {}).get(name, []))
            pin = data.get("pins", {}).get(name)
            rows = [row for row in packages[name]
                    if row["version"] not in blocked
                    and (pin is None or row["version"] == pin)
                    and all(low <= row["version"] <= high for low, high in bounds)]
            for row in rows:
                version = row["version"]
                new_req = {n: list(items) for n, items in req.items()}
                new_chosen = dict(chosen)
                new_edges = {n: list(items) for n, items in edges.items()}
                new_chosen[name] = version
                deps = [d for d in row.get("deps", [])
                        if not d.get("feature") or d["feature"] in features]
                new_edges[name] = [d["name"] for d in deps]
                valid = True
                for dep in deps:
                    target = dep["name"]
                    low, high = dep["min"], dep["max"]
                    new_req.setdefault(target, []).append((low, high))
                    if target in new_chosen and not low <= new_chosen[target] <= high:
                        valid = False
                        break
                if valid and not cyclic(new_edges):
                    search(new_req, new_chosen, new_edges)

        search(initial, {}, {})
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def ledger(data):
    def rounded(num, den, mode):
        return (num + den // 2) // den if mode == "half_up" else num // den

    balances = dict(data.get("opening", {}))
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, data["rounding"])
        tax = rounded(raw * event.get("tax_bp", 0), 10000, data["rounding"])
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def quota_intervals(data):
    jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    if mandatory & set(data.get("blocked", [])):
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    k = data["k"]
    if k > len(jobs):
        return {"error": "impossible"}
    for subset in combinations(jobs, k):
        ids = tuple(sorted(j["id"] for j in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        feasible = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            heapq.heappush(active, job["end"])
            if len(active) > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(j["value"] for j in subset)
        if best_value is None or value > best_value or (value == best_value and ids > best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    bits = {node: sum(1 << i for i, r in enumerate(required) if r == node)
            for node in range(data["n"])}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source, start = data["source"], data["start"]
    initial_mask = bits[source]
    initial = (source, initial_mask, data["coupons"])
    dist = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits[next_node]
                nxt = (next_node, next_mask, left)
                if arrival < dist.get(nxt, float("inf")):
                    dist[nxt] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))
    return {"arrival": None}


